// v19-dev: limite visual de eventos + visor sobreposto na data
const RT_EVENTOS_ITENS_KEY = "novoRioTendasEventosItensPorPaginaV19";

function rtEventosItensPorPaginaAtual() {
  const valor = localStorage.getItem(RT_EVENTOS_ITENS_KEY) || "10";
  if (valor === "todos") return "todos";

  const numero = Number(valor);
  return Number.isFinite(numero) && numero > 0 ? numero : 10;
}

function rtConfigurarControleItensEventos() {
  const select = document.getElementById("eventosItensPorPagina");
  if (!select || select.dataset.rtOk === "1") return;

  select.value = localStorage.getItem(RT_EVENTOS_ITENS_KEY) || "10";

  select.addEventListener("change", () => {
    localStorage.setItem(RT_EVENTOS_ITENS_KEY, select.value);
    rtAplicarVisualEventos();
  });

  select.dataset.rtOk = "1";
}

function rtStatusDataEvento(valor) {
  const iso = String(valor || "").slice(0, 10);
  if (!iso) return "futuro";

  const data = new Date(`${iso}T00:00:00`);
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);

  if (isNaN(data.getTime())) return "futuro";
  if (data.getTime() < hoje.getTime()) return "passado";
  if (data.getTime() === hoje.getTime()) return "hoje";
  return "futuro";
}

function rtAplicarVisualEventos() {
  rtConfigurarControleItensEventos();

  const tbody = document.getElementById("eventosTbody");
  if (!tbody) return;

  const limite = rtEventosItensPorPaginaAtual();
  const linhas = Array.from(tbody.querySelectorAll("tr")).filter(tr => !tr.querySelector(".empty"));

  linhas.forEach((tr, index) => {
    tr.style.display = limite === "todos" || index < limite ? "" : "none";
  });
}

function rtDepoisRenderizarEventosLista() {
  setTimeout(rtAplicarVisualEventos, 0);
}



function obterTimestampOrdenacaoEvento(evento) {
  const data = evento?.data_evento || evento?.data || evento?.montagem || evento?.inicio || "";
  const hora = evento?.hora_evento || evento?.hora_inicio || evento?.horario || "00:00";

  if (!data) return Number.MAX_SAFE_INTEGER;

  const dataNormalizada = String(data).includes("T")
    ? String(data)
    : `${String(data).slice(0, 10)}T${String(hora || "00:00").slice(0, 5) || "00:00"}`;

  const ts = new Date(dataNormalizada).getTime();
  return Number.isFinite(ts) ? ts : Number.MAX_SAFE_INTEGER;
}

function ordenarEventosPorData(listaEventos) {
  if (!Array.isArray(listaEventos)) return [];

  return [...listaEventos].sort((a, b) => {
    const dataA = obterTimestampOrdenacaoEvento(a);
    const dataB = obterTimestampOrdenacaoEvento(b);

    if (dataA !== dataB) return dataA - dataB;

    const nomeA = String(a?.nome || a?.cliente || "").toLowerCase();
    const nomeB = String(b?.nome || b?.cliente || "").toLowerCase();

    return nomeA.localeCompare(nomeB, "pt-BR");
  });
}

function normalizarOrdemEventosGlobal() {
  if (Array.isArray(eventos)) {
    eventos = ordenarEventosPorData(eventos);
  }
}

function dataCompactaComDiaRecorrente(dataISO) {
  if (!dataISO) return "-";

  const partes = String(dataISO).split("-");
  if (partes.length < 3) return dataISO;

  const data = new Date(`${dataISO}T12:00:00`);
  const dias = ["dom", "seg", "ter", "qua", "qui", "sex", "sáb"];

  const dd = partes[2];
  const mm = partes[1];
  const aa = partes[0].slice(-2);

  return `<span class="event-date-strong">${dd}/${mm}/${aa}</span> <span class="event-weekday-light">${dias[data.getDay()]}</span>`;
}



