function dinheiro(valor) {
  return Number(valor || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}
function moedaParaNumero(valor) {
  if (typeof valor === "number") return valor;

  let texto = String(valor || "")
    .replace("R$", "")
    .trim();

  if (!texto) return 0;

  // Se o usuário digitar 80, interpreta como R$ 80,00.
  // Se digitar 80,50 ou 80.50, interpreta como R$ 80,50.
  if (texto.includes(",") || texto.includes(".")) {
    texto = texto.replace(/\./g, "").replace(",", ".");
    const numero = Number(texto.replace(/[^\d.]/g, ""));
    return Number.isNaN(numero) ? 0 : numero;
  }

  const numeroInteiro = Number(texto.replace(/\D/g, ""));
  return Number.isNaN(numeroInteiro) ? 0 : numeroInteiro;
}

function numeroParaMoeda(valor) {
  return dinheiro(Number(valor || 0));
}

function formatarCampoMoeda(input) {
  input.value = numeroParaMoeda(moedaParaNumero(input.value));
}

function dataBR(dataISO) {
  if (!dataISO) return "-";
  const partes = String(dataISO).split("-");
  if (partes.length !== 3) return dataISO;
  return `${partes[2]}/${partes[1]}/${partes[0].slice(-2)}`;
}


function diaSemanaTexto(data) {
  if (!data) return "";
  const dias = ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"];
  const d = new Date(data + "T12:00:00");
  return dias[d.getDay()] || "";
}

function diaSemana(dataISO) {
  if (!dataISO) return "-";
  const data = new Date(dataISO + "T12:00:00");
  return data.toLocaleDateString("pt-BR", { weekday: "short" });
}


function tipoHorarioBase(valor) {
  return String(valor || "Horário comercial").split("|")[0] || "Horário comercial";
}

function tipoHorarioFim(valor) {
  const partes = String(valor || "").split("|");
  return partes.length > 1 ? partes[1] : "";
}

function montarTipoHorarioParaSalvar(selectId, fimId) {
  const tipo = document.getElementById(selectId)?.value || "A partir de";
  const fim = document.getElementById(fimId)?.value || "";
  return tipo === "Intervalo" && fim ? `${tipo}|${fim}` : tipo;
}

function textoHorarioOperacao(tipoSalvo, datetimeValor) {
  if (!datetimeValor) return "-";

  const tipo = tipoHorarioBase(tipoSalvo);
  const fim = tipoHorarioFim(tipoSalvo);
  const dataTxt = formatarData(datetimeValor);
  const hora = String(datetimeValor || "").slice(11, 16);

  if (tipo === "Exatamente") return `Exatamente ${dataTxt}`;
  if (tipo === "A partir de") return `A partir de ${dataTxt}`;
  if (tipo === "Até") return `Até ${dataTxt}`;
  if (tipo === "Intervalo") {
    return fim ? `Entre ${dataTxt} e ${fim}` : `Intervalo a partir de ${dataTxt}`;
  }
  if (tipo === "Horário comercial") return `${dataBR(String(datetimeValor).slice(0, 10))} — Horário comercial`;
  if (tipo === "Livre / combinar") return `${dataBR(String(datetimeValor).slice(0, 10))} — Livre / combinar`;

  return `${tipo} ${dataTxt}`;
}

function preencherSelectsHorarioEvento() {
  const ids = ["eventoHoraInicio", "eventoHoraTermino", "eventoMontagemHora", "eventoDesmontagemHora", "eventoMontagemFim", "eventoDesmontagemFim"];
  const opcoes = ['<option value="">Livre</option>'];
  for (let h = 0; h < 24; h++) {
    for (let m = 0; m < 60; m += 30) {
      const valor = `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
      opcoes.push(`<option value="${valor}">${valor}</option>`);
    }
  }
  ids.forEach(id => {
    const el = document.getElementById(id);
    if (!el || el.dataset.horariosCarregados === "1") return;
    const valorAtual = el.value || "";
    el.innerHTML = opcoes.join("");
    el.value = valorAtual;
    el.dataset.horariosCarregados = "1";
  });
}

function separarDataHoraEvento(valor) {
  const texto = String(valor || "");
  if (!texto) return { data: "", hora: "" };
  if (texto.includes("T")) return { data: texto.slice(0, 10), hora: texto.slice(11, 16) };
  return { data: texto.slice(0, 10), hora: "" };
}

function montarDataHoraEvento(data, hora) {
  if (!data) return null;
  return `${data}T${hora || "00:00"}`;
}

function atualizarCampoHoraFinalOperacao(prefixo) {
  const select = document.getElementById(`evento${prefixo}Tipo`);
  const box = document.getElementById(`evento${prefixo}FimBox`);
  const input = document.getElementById(`evento${prefixo}Fim`);
  const campoDataHora = document.getElementById(`evento${prefixo}`);
  const campoHora = document.getElementById(`evento${prefixo}Hora`);

  if (!select || !box || !input || !campoDataHora) return;

  const tipo = select.value;
  const mostrarHoraFinal = tipo === "Intervalo";
  box.style.display = mostrarHoraFinal ? "" : "none";
  if (!mostrarHoraFinal) input.value = "";

  const partes = separarDataHoraEvento(campoDataHora.value || "");
  campoDataHora.type = "date";
  campoDataHora.required = false;
  campoDataHora.value = partes.data || campoDataHora.value || "";

  if (campoHora && !campoHora.value && partes.hora && partes.hora !== "00:00") {
    campoHora.value = partes.hora;
  }
}

function aplicarTipoHorarioNoFormulario(prefixo, valorSalvo) {
  const select = document.getElementById(`evento${prefixo}Tipo`);
  const input = document.getElementById(`evento${prefixo}Fim`);
  if (!select || !input) return;

  select.value = tipoHorarioBase(valorSalvo);
  input.value = tipoHorarioFim(valorSalvo);
  atualizarCampoHoraFinalOperacao(prefixo);
}

async function buscarEventosBanco() {
  if (!supabaseClient) {
    return JSON.parse(localStorage.getItem(storageEventosKey) || "[]");
  }

  const { data, error } = await supabaseClient
    .from("eventos")
    .select("*")
    .order("data_evento", { ascending: true });

  if (error) {
    console.error("Erro Supabase ao buscar eventos:", error);
    alert("Erro ao buscar eventos no Supabase: " + (error.message || ""));
    return [];
  }

  return data || [];
}

async function salvarEventoBanco(evento) {
  const eventoAntesLog = Array.isArray(eventos)
    ? eventos.find(e => String(e.id) === String(evento.id))
    : null;
  const eventoEhRecorrenteLog = Boolean(evento.recorrente || evento.recorrencia_grupo_id || eventoAntesLog?.recorrente || eventoAntesLog?.recorrencia_grupo_id);
  const moduloLogEvento = eventoEhRecorrenteLog ? "Eventos Recorrentes" : "Eventos";
  const acaoLogEvento = eventoAntesLog
    ? (eventoEhRecorrenteLog ? "Evento recorrente editado" : "Evento editado")
    : (eventoEhRecorrenteLog ? "Evento recorrente cadastrado" : "Evento cadastrado");

  if (!supabaseClient) {
    const i = eventos.findIndex(e => e.id === evento.id);
    if (i >= 0) eventos[i] = evento;
    else eventos.push(evento);
    localStorage.setItem(storageEventosKey, JSON.stringify(eventos));

    if (typeof registrarLogSistema === "function") {
      registrarLogSistema({
        modulo: moduloLogEvento,
        acao: acaoLogEvento,
        registro_id: evento.id,
        registro_nome: evento.nome || "Evento",
        antes: eventoAntesLog || null,
        depois: evento
      });
    }

    return evento;
  }

  const eventoSupabase = {
    id: evento.id,
    nome: evento.nome || "",
    documento: evento.documento || null,
    telefone: evento.telefone || null,
    cliente_email: evento.cliente_email || evento.email || null,
    endereco: evento.endereco || null,
    bairro: evento.bairro || null,
    cidade: evento.cidade || (typeof carregarConfiguracoes === "function" ? (carregarConfiguracoes().cidadePadrao || "Rio de Janeiro") : "Rio de Janeiro"),
    complemento: evento.complemento || null,
    cliente_observacao: evento.cliente_observacao || null,
    data_evento: evento.data_evento || null,
    hora_evento: evento.hora_inicio || evento.hora_evento || null,
    hora_inicio: evento.hora_inicio || evento.hora_evento || null,
    hora_termino: evento.hora_termino || null,
    montagem_tipo: evento.montagem_tipo || "A partir de",
    montagem: evento.montagem || null,
    desmontagem_tipo: evento.desmontagem_tipo || "A partir de",
    desmontagem: evento.desmontagem || null,
    tendas: evento.tendas || [],
    itens_apoio: evento.itens_apoio || [],
    produtos_extras: evento.produtos_extras || [],
    valor_total: Number(evento.valor_total || 0),
    valor_sinal: Number(evento.valor_sinal || 0),
    valor_restante: Number(evento.valor_restante || 0),
    forma_pagamento: evento.forma_pagamento || null,
    pagamento_quitado: Boolean(evento.pagamento_quitado),
    assinatura_status: rtAssinaturaStatusEvento(evento),
    assinatura_link: evento.assinatura_link || null,
    assinatura_enviada_em: evento.assinatura_enviada_em || null,
    assinatura_realizada_em: evento.assinatura_realizada_em || null,
    status_evento: evento.status_evento || "ativo",
    colaborador: evento.colaborador || getColaboradorLogado(),
    criado_em: evento.criado_em || new Date().toISOString(),
    atualizado_em: new Date().toISOString(),
    tipo_evento: evento.tipo_evento || "pontual",
    recorrente: Boolean(evento.recorrente),
    recorrencia_grupo_id: evento.recorrencia_grupo_id || null,
    recorrencia_tipo: evento.recorrencia_tipo || null,
    recorrencia_dias: evento.recorrencia_dias || null,
    recorrencia_inicio: evento.recorrencia_inicio || null,
    recorrencia_fim: evento.recorrencia_fim || null,
    recorrencia_ordem: evento.recorrencia_ordem || null
  };

  const { data, error } = await supabaseClient
    .from("eventos")
    .upsert(eventoSupabase, { onConflict: "id" })
    .select()
    .single();

  if (error) {
    console.error("Erro Supabase ao salvar evento:", error);
    alert("Erro ao salvar evento no Supabase: " + (error.message || ""));
    return null;
  }

  if (typeof registrarLogSistema === "function") {
    registrarLogSistema({
      modulo: moduloLogEvento,
      acao: acaoLogEvento,
      registro_id: data.id,
      registro_nome: data.nome || "Evento",
      antes: eventoAntesLog || null,
      depois: data
    });
  }

  return data;
}

async function excluirEventoBanco(id) {
  // Mantido apenas para compatibilidade. A ação padrão agora é cancelar, não excluir.
  const eventoAntesLog = Array.isArray(eventos)
    ? eventos.find(e => String(e.id) === String(id))
    : null;

  if (!supabaseClient) {
    eventos = eventos.filter(e => e.id !== id);
    localStorage.setItem(storageEventosKey, JSON.stringify(eventos));
    return true;
  }

  const { error } = await supabaseClient.from("eventos").delete().eq("id", id);

  if (error) {
    alert("Erro ao excluir evento: " + (error.message || ""));
    return false;
  }

  if (typeof registrarLogSistema === "function") {
    registrarLogSistema({
      modulo: (eventoAntesLog?.recorrente || eventoAntesLog?.recorrencia_grupo_id) ? "Eventos Recorrentes" : "Eventos",
      acao: (eventoAntesLog?.recorrente || eventoAntesLog?.recorrencia_grupo_id) ? "Evento recorrente excluído" : "Evento excluído",
      registro_id: id,
      registro_nome: eventoAntesLog?.nome || "Evento",
      antes: eventoAntesLog || null,
      depois: null
    });
  }

  return true;
}


async function rtLiberarProdutosEventoCancelado(eventoCancelado) {
  try {
    if (!eventoCancelado) return;
    const codigos = new Set();
    const coletar = (lista) => (Array.isArray(lista) ? lista : []).forEach(item => {
      const codigo = String(item?.codigo || item?.produto_codigo || item?.id || item || "").trim();
      if (codigo) codigos.add(codigo);
    });
    coletar(eventoCancelado.produtos);
    coletar(eventoCancelado.itens);
    coletar(eventoCancelado.produtos_selecionados);
    if (!codigos.size && eventoCancelado.produtos_texto) {
      String(eventoCancelado.produtos_texto).split(/[,;\n]+/).forEach(t => { const m = t.match(/\b[A-Z]*\d+[A-Z0-9-]*\b/i); if (m) codigos.add(m[0]); });
    }
    if (!Array.isArray(produtos) || !codigos.size) return;
    const nome = String(eventoCancelado.nome || "").toLowerCase();
    for (const produto of produtos) {
      const codigo = String(produto.codigo || produto.id || "").trim();
      if (!codigos.has(codigo)) continue;
      const statusAtual = String(produto.status || "").toLowerCase();
      const obs = String(produto.observacao || "");
      const locacoes = Array.isArray(produto.locacoes) ? produto.locacoes : [];
      const ligadoAoEvento = locacoes.some(l => String(l?.evento_id || l?.id || "") === String(eventoCancelado.id)) || (nome && obs.toLowerCase().includes(nome));
      if (statusAtual === "alugado" || ligadoAoEvento) {
        produto.status = "Livre";
        produto.colaborador = typeof getColaboradorLogado === "function" ? getColaboradorLogado() : produto.colaborador;
        if (ligadoAoEvento || obs.toLowerCase().includes("alugad")) produto.observacao = "";
        produto.locacoes = locacoes.filter(l => String(l?.evento_id || l?.id || "") !== String(eventoCancelado.id));
        produto.atualizado_em = new Date().toISOString();
        if (typeof salvarProdutoBanco === "function") await salvarProdutoBanco(produto);
      }
    }
    if (typeof renderizarProdutos === "function") renderizarProdutos();
  } catch (err) {
    console.warn("Não foi possível liberar todos os produtos do evento cancelado:", err);
  }
}

function rtLimparOperacoesRotasEventoCancelado(eventoId) {
  try {
    if (!eventoId || typeof rotasOperacao !== "object" || !rotasOperacao) return;
    let alterou = false;
    Object.keys(rotasOperacao).forEach(chave => {
      if (String(rotasOperacao[chave]?.evento_id || "") === String(eventoId)) {
        delete rotasOperacao[chave];
        alterou = true;
      }
    });
    if (alterou && typeof salvarRotasOperacaoLocal === "function") salvarRotasOperacaoLocal();
  } catch (err) {
    console.warn("Não foi possível limpar status de rota do evento cancelado:", err);
  }
}

async function atualizarStatusEventoBanco(id, status) {
  const eventoAntesLog = Array.isArray(eventos)
    ? eventos.find(e => String(e.id) === String(id))
    : null;
  if (!eventoAntesLog) return false;

  const atualizado = {
    ...eventoAntesLog,
    status_evento: status,
    atualizado_em: new Date().toISOString()
  };

  const salvo = await salvarEventoBanco(atualizado);
  if (!salvo) return false;

  const idx = eventos.findIndex(e => String(e.id) === String(id));
  if (idx >= 0) eventos[idx] = salvo;
  else eventos.push(salvo);

  if (typeof registrarLogSistema === "function") {
    registrarLogSistema({
      modulo: (eventoAntesLog?.recorrente || eventoAntesLog?.recorrencia_grupo_id) ? "Eventos Recorrentes" : "Eventos",
      acao: status === "cancelado" ? "Evento cancelado" : "Evento reativado",
      registro_id: id,
      registro_nome: eventoAntesLog?.nome || "Evento",
      antes: eventoAntesLog || null,
      depois: salvo
    });
  }

  return true;
}


async function atualizarPeriodoRecorrenciaAposExclusao(eventoExcluido) {
  try {
    if (!eventoExcluido || !eventoExcluido.recorrencia_grupo_id) return;
    const grupoId = String(eventoExcluido.recorrencia_grupo_id);
    const restantes = (Array.isArray(eventos) ? eventos : [])
      .filter(e => String(e.recorrencia_grupo_id || "") === grupoId && String(e.id) !== String(eventoExcluido.id))
      .sort((a, b) => String(a.data_evento || "").localeCompare(String(b.data_evento || "")));

    if (!restantes.length) return;

    const datas = restantes.map(e => e.data_evento).filter(Boolean).sort();
    if (!datas.length) return;

    const novoInicio = datas[0];
    const novoFim = datas[datas.length - 1];

    restantes.forEach((e, idx) => {
      e.recorrencia_inicio = novoInicio;
      e.recorrencia_fim = novoFim;
      e.recorrencia_ordem = idx + 1;
    });

    if (!supabaseClient) {
      localStorage.setItem(storageEventosKey, JSON.stringify(eventos));
      return;
    }

    await Promise.all(restantes.map((e, idx) =>
      supabaseClient
        .from("eventos")
        .update({
          recorrencia_inicio: novoInicio,
          recorrencia_fim: novoFim,
          recorrencia_ordem: idx + 1
        })
        .eq("id", e.id)
    ));

    if (typeof registrarLogSistema === "function") {
      registrarLogSistema({
        modulo: "Eventos Recorrentes",
        acao: "Período de recorrência atualizado após exclusão",
        registro_id: grupoId,
        registro_nome: eventoExcluido.nome || "Recorrência",
        antes: {
          recorrencia_inicio: eventoExcluido.recorrencia_inicio || null,
          recorrencia_fim: eventoExcluido.recorrencia_fim || null
        },
        depois: {
          recorrencia_inicio: novoInicio,
          recorrencia_fim: novoFim,
          ocorrencias_restantes: restantes.length
        }
      });
    }
  } catch (err) {
    console.warn("Não foi possível atualizar o período restante da recorrência:", err);
  }
}

async function garantirClienteDoEvento(evento) {
  if (!evento.nome) return null;

  const documento = String(evento.documento || "").trim();
  const telefone = String(evento.telefone || "").trim();
  const emailEvento = String(evento.cliente_email || evento.email || "").trim();
  const observacaoEvento = String(evento.cliente_observacao || "").trim();

  let existente = null;

  if (Array.isArray(clientes)) {
    existente = clientes.find(c =>
      (documento && String(c.documento || "").trim() === documento) ||
      (telefone && String(c.telefone || "").trim() === telefone) ||
      (String(c.nome || "").toLowerCase() === String(evento.nome || "").toLowerCase())
    );
  }

  if (typeof salvarClienteBanco !== "function") return existente || null;

  if (existente) {
    const atualizado = {
      ...existente,
      nome: evento.nome || existente.nome || "",
      documento: documento || existente.documento || "",
      telefone: telefone || existente.telefone || "",
      email: emailEvento || existente.email || "",
      endereco: evento.endereco || existente.endereco || "",
      bairro: evento.bairro || existente.bairro || "",
      cidade: evento.cidade || existente.cidade || (typeof carregarConfiguracoes === "function" ? (carregarConfiguracoes().cidadePadrao || "Rio de Janeiro") : "Rio de Janeiro"),
      complemento: evento.complemento || existente.complemento || "",
      observacao_cliente: observacaoEvento || existente.observacao_cliente || "",
      colaborador: existente.colaborador || getColaboradorLogado()
    };

    const mudou = JSON.stringify({
      nome: existente.nome || "",
      documento: existente.documento || "",
      telefone: existente.telefone || "",
      email: existente.email || "",
      endereco: existente.endereco || "",
      bairro: existente.bairro || "",
      cidade: existente.cidade || "",
      complemento: existente.complemento || "",
      observacao_cliente: existente.observacao_cliente || ""
    }) !== JSON.stringify({
      nome: atualizado.nome || "",
      documento: atualizado.documento || "",
      telefone: atualizado.telefone || "",
      email: atualizado.email || "",
      endereco: atualizado.endereco || "",
      bairro: atualizado.bairro || "",
      cidade: atualizado.cidade || "",
      complemento: atualizado.complemento || "",
      observacao_cliente: atualizado.observacao_cliente || ""
    });

    if (!mudou) return existente;

    const salvo = await salvarClienteBanco(atualizado);
    if (salvo && Array.isArray(clientes)) {
      const idx = clientes.findIndex(c => String(c.id) === String(salvo.id));
      if (idx >= 0) clientes[idx] = salvo;
      else clientes.push(salvo);
      if (typeof renderizarClientes === "function") renderizarClientes();
    }
    return salvo || atualizado;
  }

  const cliente = {
    id: gerarId(),
    nome: evento.nome,
    documento: documento,
    telefone: telefone,
    email: emailEvento,
    endereco: evento.endereco || "",
    bairro: evento.bairro || "",
    cidade: evento.cidade || (typeof carregarConfiguracoes === "function" ? (carregarConfiguracoes().cidadePadrao || "Rio de Janeiro") : "Rio de Janeiro"),
    complemento: evento.complemento || "",
    observacao_cliente: observacaoEvento,
    colaborador: getColaboradorLogado(),
    criado_em: new Date().toISOString()
  };

  const salvo = await salvarClienteBanco(cliente);

  if (salvo && Array.isArray(clientes)) {
    clientes.push(salvo);
    if (typeof renderizarClientes === "function") renderizarClientes();
  }

  return salvo;
}

