function extrairValorSinal2FormaPagamento(texto) {
  const m = String(texto || "").match(/Sinal 2 Valor:\s*(R\$\s*[\d.]+,\d{2})/i);
  return m ? m[1] : numeroParaMoeda(0);
}

function sincronizarSinal2FormaPagamentoEvento() {
  const campo = document.getElementById("eventoFormaPagamento");
  if (!campo) return;

  // O segundo sinal não deve criar outro campo visual. Ele fica como mais uma linha
  // dentro de Forma de pagamento, usando o mesmo padrão do primeiro sinal.
  const linhas = String(campo.value || "")
    .split(/\n+/)
    .map(l => l.trim())
    .filter(Boolean)
    .filter(l => !/^Sinal 2 Valor:/i.test(l))
    .map(l => l.replace(/^Sinal\s*2\s*-/i, "Sinal -"));

  campo.value = linhas.join("\n");
}

function iniciarIconesFormaPagamentoEvento() {
  document.querySelectorAll(".pagamento-icone[data-pagamento-forma]").forEach(btn => {
    if (btn.dataset.listenerPagamento === "1") return;
    btn.dataset.listenerPagamento = "1";
    btn.addEventListener("click", () => {
      const grupo = btn.closest(".pagamento-icones");
      const tipo = grupo?.dataset?.pagamentoTipo || "";
      const forma = btn.dataset.pagamentoForma || "";
      aplicarFormaPagamentoEvento(tipo, forma);
    });
  });
}

function aplicarFormaPagamentoEvento(tipo, forma) {
  const campo = document.getElementById("eventoFormaPagamento");
  if (!campo || !tipo || !forma) return;

  // Segundo sinal: não abre campo separado. Cada novo clique em ícone de Sinal
  // adiciona uma nova linha no campo Forma de pagamento.
  const ehSinal = tipo === "Sinal" || tipo === "Sinal 2";
  if (tipo === "Sinal 2") tipo = "Sinal";

  if (tipo === "Pg Total") {
    const inloco = document.getElementById("eventoPagarInloco");
    if (inloco?.checked) {
      inloco.checked = false;
      rtSincronizarPagarInlocoFormaPagamento();
    }
    const quitado = document.getElementById("eventoPagamentoQuitado");
    if (quitado) quitado.checked = true;
  }

  if (tipo === "Restante") {
    const restanteAtual = moedaParaNumero(document.getElementById("eventoValorRestante")?.value || 0);
    const quitado = document.getElementById("eventoPagamentoQuitado");
    const inloco = document.getElementById("eventoPagarInloco");
    if (restanteAtual <= 0 || confirm("O pagamento lançado quita o saldo restante.\n\nMarcar evento como QUITADO?")) {
      if (quitado) quitado.checked = true;
      if (inloco?.checked) {
        inloco.checked = false;
        rtSincronizarPagarInlocoFormaPagamento();
      }
    }
  }
  const marcadorData = "";
  const novaLinha = `${tipo} - ${forma} -`;
  const linhas = String(campo.value || "")
    .split(/\n+/)
    .map(l => l.trim())
    .filter(Boolean);

  const prefixo = `${tipo} - `;

  if (ehSinal) {
    // Permite sinal em duas ou mais etapas no mesmo campo Forma de pagamento.
    linhas.push(novaLinha);
  } else {
    const idx = linhas.findIndex(l => l.toLowerCase().startsWith(prefixo.toLowerCase()));

    if (idx >= 0) {
      const linhaAtual = linhas[idx];
      const temDataPreenchida = /\b\d{2}\/\d{2}\/\d{2,4}\b/.test(linhaAtual);
      if (temDataPreenchida && !confirm(`${tipo} já possui data preenchida. Deseja substituir a forma de pagamento?`)) {
        return;
      }
      linhas[idx] = novaLinha;
    } else {
      linhas.push(novaLinha);
    }
  }

  campo.value = linhas.join("\n");
  campo.focus();
  atualizarIconesFormaPagamentoEvento();
  atualizarQuitadoAutomaticoEvento();
}

function atualizarIconesFormaPagamentoEvento() {
  const texto = document.getElementById("eventoFormaPagamento")?.value || "";
  document.querySelectorAll(".pagamento-icones").forEach(grupo => {
    const tipo = grupo.dataset.pagamentoTipo || "";
    grupo.querySelectorAll(".pagamento-icone").forEach(btn => {
      const forma = btn.dataset.pagamentoForma || "";
      const ativo = texto.toLowerCase().includes(`${tipo} - ${forma}`.toLowerCase());
      btn.classList.toggle("ativo", ativo);
    });
  });
}

function rtEventoPagarInlocoMarcado(evento) {
  return Boolean(evento?.pagar_inloco) || /(^|\n)\s*(pagar\s+in\s*loco|in\s*loco\s*\/\s*faturado)\s*($|\n)/i.test(String(evento?.forma_pagamento || ""));
}

function rtSincronizarPagarInlocoFormaPagamento() {
  const campo = document.getElementById("eventoFormaPagamento");
  const chk = document.getElementById("eventoPagarInloco");
  if (!campo || !chk) return;

  let linhas = String(campo.value || "")
    .split(/\n+/)
    .map(l => l.trim())
    .filter(Boolean)
    .filter(l => !/^(pagar\s+in\s*loco|in\s*loco\s*\/\s*faturado)$/i.test(l));

  if (chk.checked) {
    linhas.push("In loco / Faturado");
  }

  campo.value = linhas.join("\n");
  atualizarIconesFormaPagamentoEvento();
}

function rtIniciarPagarInlocoEvento() {
  const chk = document.getElementById("eventoPagarInloco");
  if (!chk || chk.dataset.listenerInloco === "1") return;
  chk.dataset.listenerInloco = "1";
  chk.addEventListener("change", () => {
    rtSincronizarPagarInlocoFormaPagamento();
    if (chk.checked) {
      const quitado = document.getElementById("eventoPagamentoQuitado");
      if (quitado) quitado.checked = false;
    }
  });
}


function isEventoRecorrente(evento) {
  return Boolean(evento.recorrente || evento.tipo_evento === "recorrente" || evento.recorrencia_grupo_id);
}


function rtRecorrenciaPeriodoLinhaHtml(e) {
  if (!e || !isEventoRecorrente(e)) return dataCompactaComDiaRecorrente(e?.data_evento);
  const inicio = String(e.data_evento || e.recorrencia_inicio || '').slice(0, 10);
  if (!inicio) return '-';
  let fim = inicio;
  const tipo = e.recorrencia_tipo || 'mensal';
  if (tipo === 'mensal') fim = addMesISO(inicio, 1);
  else if (tipo === 'quinzenal') fim = addDiasISO(inicio, 15);
  else fim = addDiasISO(inicio, Number(e.recorrencia_dias || 30));
  const fimGeral = String(e.recorrencia_fim || '').slice(0, 10);
  if (fimGeral && fim > fimGeral) fim = fimGeral;
  return `<div class="rec-period-line">${dataCompactaComDiaRecorrente(inicio)}</div><div class="rec-period-line rec-period-end">${dataCompactaComDiaRecorrente(fim)}</div>`;
}

function recorrenciaLabel(tipo, dias) {
  if (tipo === "mensal") return "Mensal";
  if (tipo === "quinzenal") return "A cada 15 dias";
  if (tipo === "personalizado") return `A cada ${dias || 1} dias`;
  return "-";
}

function addDiasISO(dataISO, dias) {
  const d = new Date(`${dataISO}T12:00:00`);
  d.setDate(d.getDate() + Number(dias || 0));
  return d.toISOString().slice(0, 10);
}

function addMesISO(dataISO, meses) {
  const d = new Date(`${dataISO}T12:00:00`);
  d.setMonth(d.getMonth() + Number(meses || 0));
  return d.toISOString().slice(0, 10);
}

function diffDiasISO(base, alvo) {
  const b = new Date(`${base}T12:00:00`);
  const a = new Date(`${alvo}T12:00:00`);
  return Math.round((a.getTime() - b.getTime()) / (1000 * 60 * 60 * 24));
}

function ajustarDatetimePelaNovaData(datetimeOriginal, dataOriginal, dataNova) {
  if (!datetimeOriginal || !dataOriginal || !dataNova) return datetimeOriginal || null;
  return String(datetimeOriginal).replace(String(dataOriginal), String(dataNova));
}

function datasRecorrencia(inicio, fim, tipo, diasPersonalizado) {
  if (!inicio || !fim) return [];

  const datas = [];
  let atual = inicio;
  let seguranca = 0;

  while (atual <= fim && seguranca < 120) {
    datas.push(atual);

    if (tipo === "mensal") atual = addMesISO(atual, 1);
    else if (tipo === "quinzenal") atual = addDiasISO(atual, 15);
    else atual = addDiasISO(atual, Math.max(Number(diasPersonalizado || 1), 1));

    seguranca++;
  }

  return datas;
}

function atualizarBoxRecorrencia() {
  const tipoEvento = document.getElementById("eventoTipoEvento")?.value || "pontual";
  const box = document.getElementById("eventoRecorrenciaBox");
  if (!box) return;

  box.classList.toggle("hidden", tipoEvento !== "recorrente");
}

function atualizarCampoDiasRecorrencia() {
  const tipo = document.getElementById("eventoRecorrenciaTipo")?.value || "mensal";
  const campo = document.getElementById("eventoRecorrenciaDias");
  if (!campo) return;

  campo.disabled = tipo !== "personalizado";
  if (tipo === "mensal") campo.value = 30;
  if (tipo === "quinzenal") campo.value = 15;
}

function preencherDatasRecorrenciaPadrao() {
  const dataEvento = document.getElementById("eventoData")?.value || "";
  const inicio = document.getElementById("eventoRecorrenciaInicio");
  const fim = document.getElementById("eventoRecorrenciaFim");

  if (inicio && dataEvento && !inicio.value) inicio.value = dataEvento;
  if (fim && dataEvento && !fim.value) fim.value = addMesISO(dataEvento, 6);
}


function valorOperacaoParaSalvar(campoId, tipoSelectId) {
  const campo = document.getElementById(campoId);
  const select = document.getElementById(tipoSelectId);
  const valor = campo?.value || "";
  const tipo = select?.value || "";

  if (!valor) return null;

  const horaId = campoId === "eventoMontagem" ? "eventoMontagemHora" : (campoId === "eventoDesmontagem" ? "eventoDesmontagemHora" : null);
  const hora = horaId ? (document.getElementById(horaId)?.value || "") : "";

  if (valor.includes("T")) return valor;
  if (tipo === "Horário comercial" || tipo === "Livre / combinar") return `${valor}T00:00`;
  return montarDataHoraEvento(valor, hora || "09:00");
}

