// v19-dev: ao trocar quantidade, manter o primeiro evento visível como referência
function rtPrimeiroEventoVisivelAtual() {
  const tbody = document.getElementById("eventosTbody");
  const wrapper = tbody?.closest(".eventos-table-scroll") || tbody?.closest(".table-wrapper");

  if (!tbody || !wrapper) return null;

  const linhas = Array.from(tbody.querySelectorAll("tr"))
    .filter(tr => tr.style.display !== "none" && !tr.querySelector(".empty"));

  if (!linhas.length) return null;

  const topoWrapper = wrapper.getBoundingClientRect().top;

  let melhor = linhas[0];
  let menorDistancia = Infinity;

  linhas.forEach(tr => {
    const rect = tr.getBoundingClientRect();
    const distancia = Math.abs(rect.top - topoWrapper);

    if (rect.bottom >= topoWrapper && distancia < menorDistancia) {
      melhor = tr;
      menorDistancia = distancia;
    }
  });

  const id = melhor.querySelector("[data-id]")?.dataset?.id || "";
  return { id, linha: melhor };
}

function rtRolarParaEventoReferencia(eventoReferencia) {
  if (!eventoReferencia?.id) return;

  const tbody = document.getElementById("eventosTbody");
  const wrapper = tbody?.closest(".eventos-table-scroll") || tbody?.closest(".table-wrapper");

  if (!tbody || !wrapper) return;

  const alvo = tbody.querySelector(`[data-id="${eventoReferencia.id}"]`)?.closest("tr");

  if (!alvo) return;

  wrapper.scrollTop = Math.max(0, alvo.offsetTop - tbody.offsetTop);
}

