// v19-dev: quantidade de eventos por altura/rolagem, sem esconder linhas
function rtAlturaLinhaEventoMedia() {
  const tbody = document.getElementById("eventosTbody");
  const primeiraLinha = tbody?.querySelector("tr:not([style*='display: none'])");
  if (!primeiraLinha) return 74;

  const altura = primeiraLinha.getBoundingClientRect().height;
  return altura && altura > 20 ? altura : 74;
}

function rtAplicarQuantidadeEventosPorAltura() {
  const select = document.getElementById("eventosItensPorPagina");
  const tbody = document.getElementById("eventosTbody");
  const wrapper = tbody?.closest(".eventos-table-scroll") || tbody?.closest(".table-wrapper");

  if (!select || !tbody || !wrapper) return;

  const valor = select.value || localStorage.getItem("novoRioTendasEventosItensPorPaginaV19") || "10";
  localStorage.setItem("novoRioTendasEventosItensPorPaginaV19", valor);

  // Reexibe todas as linhas. A limitação agora é feita pela altura da tabela com rolagem.
  Array.from(tbody.querySelectorAll("tr")).forEach(tr => {
    tr.style.display = "";
  });

  if (valor === "todos") {
    wrapper.style.maxHeight = "";
    wrapper.style.overflowY = "auto";
    return;
  }

  const quantidade = Math.max(1, Number(valor) || 10);
  const alturaLinha = rtAlturaLinhaEventoMedia();
  const alturaCabecalho = wrapper.querySelector("thead")?.getBoundingClientRect().height || 42;
  const folga = 18;

  wrapper.style.maxHeight = `${Math.ceil((alturaLinha * quantidade) + alturaCabecalho + folga)}px`;
  wrapper.style.overflowY = "auto";
}

function rtInstalarQuantidadeEventosPorAltura() {
  const select = document.getElementById("eventosItensPorPagina");
  const tbody = document.getElementById("eventosTbody");

  if (select && select.dataset.rtAlturaScroll !== "1") {
    select.value = localStorage.getItem("novoRioTendasEventosItensPorPaginaV19") || "10";

    select.addEventListener("change", () => {
      const wrapper = tbody?.closest(".eventos-table-scroll") || tbody?.closest(".table-wrapper");
      const scrollAnterior = wrapper ? wrapper.scrollTop : 0;

      rtAplicarQuantidadeEventosPorAltura();

      // Mantém o ponto atual da rolagem; não volta para o primeiro evento da tabela.
      if (wrapper) wrapper.scrollTop = scrollAnterior;
    });

    select.dataset.rtAlturaScroll = "1";
  }

  if (tbody && tbody.dataset.rtAlturaScrollObserver !== "1") {
    const observer = new MutationObserver(() => {
      setTimeout(rtAplicarQuantidadeEventosPorAltura, 50);
    });
    observer.observe(tbody, { childList: true, subtree: false });
    tbody.dataset.rtAlturaScrollObserver = "1";
  }

  setTimeout(rtAplicarQuantidadeEventosPorAltura, 50);
}

