// v19-dev: navegação rápida na tela de eventos e limite visual dos recorrentes
const RT_EVENTOS_RECORRENTES_ITENS_KEY = "novoRioTendasEventosRecorrentesItensPorPaginaV19";

function rtDataISOHojeEventos() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const dia = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${dia}`;
}

function rtAddDiasISOEventos(iso, dias) {
  const d = iso ? new Date(`${String(iso).slice(0, 10)}T12:00:00`) : new Date();
  d.setDate(d.getDate() + dias);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function rtAddMesesISOEventos(iso, meses) {
  const d = iso ? new Date(`${String(iso).slice(0, 10)}T12:00:00`) : new Date();
  d.setMonth(d.getMonth() + meses, 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-01`;
}

function rtEventosDataReferenciaFiltro() {
  return document.getElementById("filtroEventoData")?.value || rtDataISOHojeEventos();
}

function rtRolarEventosParaDataAlvo(dataAlvo, modo) {
  const tbody = document.getElementById("eventosTbody");
  const wrapper = tbody?.closest(".eventos-table-scroll") || tbody?.closest(".table-wrapper");
  if (!tbody || !wrapper || !dataAlvo) return;

  const linhas = Array.from(tbody.querySelectorAll("tr")).filter(tr => !tr.querySelector(".empty"));
  if (!linhas.length) return;

  let alvo = null;
  for (const tr of linhas) {
    const id = tr.querySelector("[data-id]")?.dataset?.id;
    const ev = eventos.find(e => String(e.id) === String(id));
    const data = String(ev?.data_evento || "").slice(0, 10);
    if (!data) continue;
    if (modo === "mes") {
      if (data.slice(0, 7) === dataAlvo.slice(0, 7)) { alvo = tr; break; }
    } else if (data === dataAlvo) { alvo = tr; break; }
  }

  if (!alvo) {
    alvo = linhas.find(tr => {
      const id = tr.querySelector("[data-id]")?.dataset?.id;
      const ev = eventos.find(e => String(e.id) === String(id));
      return String(ev?.data_evento || "").slice(0, 10) >= dataAlvo;
    }) || linhas[linhas.length - 1];
  }
  wrapper.scrollTop = Math.max(0, alvo.offsetTop - tbody.offsetTop);
}

function rtEventosNavegarPara(delta, tipo) {
  const base = rtEventosDataReferenciaFiltro();
  const alvo = tipo === "mes" ? rtAddMesesISOEventos(base, delta) : (delta === 0 ? rtDataISOHojeEventos() : rtAddDiasISOEventos(base, delta));
  setTimeout(() => rtRolarEventosParaDataAlvo(alvo, tipo === "mes" ? "mes" : "dia"), 60);
}

function rtRecorrentesDataReferencia() {
  const tbody = document.getElementById("eventosRecorrentesTbody");
  const primeira = tbody?.querySelector("tr[data-id]");
  const ev = primeira ? eventos.find(e => String(e.id) === String(primeira.dataset.id)) : null;
  return String(ev?.data_evento || document.getElementById("filtroEventoData")?.value || rtDataISOHojeEventos()).slice(0, 10);
}

function rtRolarRecorrentesParaDataAlvo(dataAlvo, modo) {
  const tbody = document.getElementById("eventosRecorrentesTbody");
  const wrapper = tbody?.closest(".recurring-table-wrapper") || tbody?.closest(".table-wrapper");
  if (!tbody || !wrapper || !dataAlvo) return;
  const linhas = Array.from(tbody.querySelectorAll("tr[data-id]"));
  if (!linhas.length) return;
  let alvo = null;
  for (const tr of linhas) {
    const ev = eventos.find(e => String(e.id) === String(tr.dataset.id));
    const data = String(ev?.data_evento || "").slice(0, 10);
    if (!data) continue;
    if (modo === "mes") {
      if (data.slice(0, 7) === dataAlvo.slice(0, 7)) { alvo = tr; break; }
    } else if (data === dataAlvo) { alvo = tr; break; }
  }
  if (!alvo) {
    alvo = linhas.find(tr => {
      const ev = eventos.find(e => String(e.id) === String(tr.dataset.id));
      return String(ev?.data_evento || "").slice(0, 10) >= dataAlvo;
    }) || linhas[linhas.length - 1];
  }
  wrapper.scrollTop = Math.max(0, alvo.offsetTop - tbody.offsetTop);
}

function rtRecorrentesNavegarPara(delta, tipo) {
  const base = rtRecorrentesDataReferencia();
  const alvo = tipo === "mes" ? rtAddMesesISOEventos(base, delta) : (delta === 0 ? rtDataISOHojeEventos() : rtAddDiasISOEventos(base, delta));
  setTimeout(() => rtRolarRecorrentesParaDataAlvo(alvo, tipo === "mes" ? "mes" : "dia"), 80);
}


function rtInstalarNavegacaoRapidaEventos() {
  const bind = (id, fn) => {
    const btn = document.getElementById(id);
    if (!btn || btn.dataset.rtNavEventos === "1") return;
    btn.addEventListener("click", fn);
    btn.dataset.rtNavEventos = "1";
  };
  bind("eventosNavMesAnterior", () => rtEventosNavegarPara(-1, "mes"));
  bind("eventosNavDiaAnterior", () => rtEventosNavegarPara(-1, "dia"));
  bind("eventosNavHoje", () => rtEventosNavegarPara(0, "dia"));
  bind("eventosNavDiaPosterior", () => rtEventosNavegarPara(1, "dia"));
  bind("eventosNavMesPosterior", () => rtEventosNavegarPara(1, "mes"));
  bind("recorrentesNavMesAnterior", () => rtRecorrentesNavegarPara(-1, "mes"));
  bind("recorrentesNavDiaAnterior", () => rtRecorrentesNavegarPara(-1, "dia"));
  bind("recorrentesNavHoje", () => rtRecorrentesNavegarPara(0, "dia"));
  bind("recorrentesNavDiaPosterior", () => rtRecorrentesNavegarPara(1, "dia"));
  bind("recorrentesNavMesPosterior", () => rtRecorrentesNavegarPara(1, "mes"));
  const filtroRec = document.getElementById("filtroRecorrentePagamento");
  if (filtroRec && filtroRec.dataset.rtRecorrentesPagamento !== "1") {
    filtroRec.addEventListener("change", () => { if (typeof renderizarEventos === "function") renderizarEventos(); });
    filtroRec.dataset.rtRecorrentesPagamento = "1";
  }
}

function rtAplicarQuantidadeRecorrentesPorAltura() {
  const select = document.getElementById("eventosRecorrentesItensPorPagina");
  const tbody = document.getElementById("eventosRecorrentesTbody");
  const wrapper = tbody?.closest(".recurring-table-wrapper") || tbody?.closest(".table-wrapper");
  if (!select || !tbody || !wrapper) return;
  const valor = select.value || localStorage.getItem(RT_EVENTOS_RECORRENTES_ITENS_KEY) || "10";
  localStorage.setItem(RT_EVENTOS_RECORRENTES_ITENS_KEY, valor);
  if (valor === "todos") { wrapper.style.maxHeight = ""; wrapper.style.overflowY = "auto"; return; }
  const quantidade = Math.max(1, Number(valor) || 10);
  const primeira = tbody.querySelector("tr");
  const altura = primeira ? Math.max(38, primeira.getBoundingClientRect().height || 58) : 58;
  const cab = wrapper.querySelector("thead")?.getBoundingClientRect().height || 42;
  wrapper.style.maxHeight = `${Math.ceil((altura * quantidade) + cab + 18)}px`;
  wrapper.style.overflowY = "auto";
}

function rtInstalarQuantidadeRecorrentes() {
  const select = document.getElementById("eventosRecorrentesItensPorPagina");
  const tbody = document.getElementById("eventosRecorrentesTbody");
  if (select && select.dataset.rtRecorrentesQtd !== "1") {
    select.value = localStorage.getItem(RT_EVENTOS_RECORRENTES_ITENS_KEY) || "10";
    select.addEventListener("change", rtAplicarQuantidadeRecorrentesPorAltura);
    select.dataset.rtRecorrentesQtd = "1";
  }
  if (tbody && tbody.dataset.rtRecorrentesObserver !== "1") {
    new MutationObserver(() => setTimeout(rtAplicarQuantidadeRecorrentesPorAltura, 50)).observe(tbody, { childList: true, subtree: false });
    tbody.dataset.rtRecorrentesObserver = "1";
  }
  rtAplicarQuantidadeRecorrentesPorAltura();
}

document.addEventListener("DOMContentLoaded", () => {
  setTimeout(rtInstalarNavegacaoRapidaEventos, 200);
  setTimeout(rtInstalarQuantidadeRecorrentes, 250);
});
document.addEventListener("click", () => {
  setTimeout(rtInstalarNavegacaoRapidaEventos, 100);
  setTimeout(rtInstalarQuantidadeRecorrentes, 150);
});
setInterval(() => { rtInstalarNavegacaoRapidaEventos(); rtInstalarQuantidadeRecorrentes(); }, 1500);

/* v19-dev: geração de documentos editáveis do evento (guia, contrato e recibo) */
function rtDocEventoTexto(valor) {
  const texto = String(valor ?? '').trim();
  return texto || '-';
}

function rtDocEventoEscape(valor) {
  return String(valor ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function rtDocEventoDataExtensoHoje() {
  return new Date().toLocaleDateString('pt-BR', {
    day: 'numeric', month: 'long', year: 'numeric'
  });
}

function rtDocEventoDataBR(valor) {
  if (!valor) return '-';
  if (typeof dataBR === 'function') return dataBR(String(valor).slice(0, 10));
  const partes = String(valor).slice(0, 10).split('-');
  return partes.length === 3 ? `${partes[2]}/${partes[1]}/${partes[0]}` : valor;
}

function rtDocEventoHora(valor) {
  const texto = String(valor || '').trim();
  if (!texto) return '-';
  if (texto.includes('T')) return texto.slice(11, 16) || '-';
  return texto.slice(0, 5);
}

function rtDocEventoOperacao(campoData, campoHora, campoTipo, campoFim) {
  const data = document.getElementById(campoData)?.value || '';
  const hora = document.getElementById(campoHora)?.value || '';
  const tipo = document.getElementById(campoTipo)?.value || '';
  const fim = document.getElementById(campoFim)?.value || '';
  const dataTxt = rtDocEventoDataBR(data);
  if (!data) return '-';
  if (tipo === 'Horário comercial') return `${dataTxt} — Horário comercial`;
  if (tipo === 'Livre / combinar') return `${dataTxt} — Livre / combinar`;
  if (tipo === 'Intervalo') return `${dataTxt} — ${hora || '-'} até ${fim || '-'}`;
  return `${tipo || ''} ${dataTxt}${hora ? ' ' + hora : ''}`.trim();
}

function rtDocEventoDescricaoServico(dados) {
  const linhas = [];
  (dados.produtos || []).forEach(item => {
    const desc = [item.codigo ? `Cód. ${item.codigo}` : '', item.categoria || '', item.tamanho || '', item.cor || ''].filter(Boolean).join(' — ');
    if (desc) linhas.push(desc);
  });
  (dados.apoio || []).forEach(item => {
    linhas.push(`${item.quantidade || 1}x ${item.nome || 'Material de apoio'}`);
  });
  (dados.extras || []).forEach(item => {
    linhas.push(`${item.quantidade || 1}x ${item.descricao || 'Extra'}`);
  });
  return linhas.length ? linhas.join('\n') : 'Locação de materiais para evento.';
}

function rtDocEventoColetarDados() {
  const dados = {
    id: document.getElementById('eventoId')?.value || '',
    nome: document.getElementById('eventoNome')?.value || '',
    documento: document.getElementById('eventoDocumento')?.value || '',
    telefone: document.getElementById('eventoTelefone')?.value || '',
    email: document.getElementById('eventoEmail')?.value || '',
    endereco: document.getElementById('eventoEndereco')?.value || '',
    observacaoCliente: document.getElementById('eventoClienteObservacao')?.value || '',
    bairro: document.getElementById('eventoBairro')?.value || '',
    cidade: document.getElementById('eventoCidade')?.value || (typeof carregarConfiguracoes === 'function' ? (carregarConfiguracoes().cidadePadrao || 'Rio de Janeiro') : 'Rio de Janeiro'),
    complemento: document.getElementById('eventoComplemento')?.value || '',
    dataEvento: document.getElementById('eventoData')?.value || '',
    horaInicio: document.getElementById('eventoHoraInicio')?.value || '',
    horaTermino: document.getElementById('eventoHoraTermino')?.value || '',
    montagem: rtDocEventoOperacao('eventoMontagem', 'eventoMontagemHora', 'eventoMontagemTipo', 'eventoMontagemFim'),
    desmontagem: rtDocEventoOperacao('eventoDesmontagem', 'eventoDesmontagemHora', 'eventoDesmontagemTipo', 'eventoDesmontagemFim'),
    valorTotal: moedaParaNumero(document.getElementById('eventoValorTotal')?.value || 0),
    valorSinal: moedaParaNumero(document.getElementById('eventoValorSinal')?.value || 0),
    valorRestante: moedaParaNumero(document.getElementById('eventoValorRestante')?.value || 0),
    formaPagamento: document.getElementById('eventoFormaPagamento')?.value || '',
    quitado: !!document.getElementById('eventoPagamentoQuitado')?.checked,
    produtos: typeof obterProdutosSelecionadosEvento === 'function' ? obterProdutosSelecionadosEvento() : (produtosSelecionadosEventoAtual || []),
    apoio: typeof obterApoioSelecionadoEvento === 'function' ? obterApoioSelecionadoEvento() : [],
    extras: Array.isArray(produtosExtrasEventoAtual) ? produtosExtrasEventoAtual : []
  };
  dados.descricaoServico = rtDocEventoDescricaoServico(dados);
  return dados;
}

function rtDocEventoLinhasTexto(texto) {
  return rtDocEventoEscape(texto || '-').replace(/\n/g, '<br>');
}


function rtDocEventoLogoEmpresaHtml() {
  const config = (typeof carregarConfiguracoes === 'function') ? carregarConfiguracoes() : (window.configRioTendas || {});
  const logo = String(config.logoEmpresa || '').trim();
  if (!logo) return '';
  return `<img src="${rtDocEventoEscape(logo)}" alt="Logo" class="doc-logo">`;
}

function rtDocEventoValorHtml(valor, multi = false) {
  const texto = rtDocEventoEscape(rtDocEventoTexto(valor));
  return multi ? texto.replace(/\n/g, '<br>') : texto;
}

function rtDocEventoAplicarModelo(template, d) {
  const horarioEvento = `${rtDocEventoHora(d.horaInicio)}${d.horaTermino ? ' às ' + rtDocEventoHora(d.horaTermino) : ''}`;
  const mapa = {
    logo_empresa: rtDocEventoLogoEmpresaHtml(),
    nome_empresa: rtDocEventoValorHtml((typeof carregarConfiguracoes === 'function' ? carregarConfiguracoes().nomeEmpresa : '') || 'RioTendas'),
    cliente: rtDocEventoValorHtml(d.nome),
    cpf_cnpj: rtDocEventoValorHtml(d.documento),
    telefone: rtDocEventoValorHtml(d.telefone),
    email: rtDocEventoValorHtml(d.email),
    endereco: rtDocEventoValorHtml((typeof rtEnderecoCompleto === "function" ? rtEnderecoCompleto(d) : d.endereco)),
    data_evento: rtDocEventoValorHtml(rtDocEventoDataBR(d.dataEvento)),
    horario_evento: rtDocEventoValorHtml(horarioEvento),
    montagem: rtDocEventoValorHtml(d.montagem),
    desmontagem: rtDocEventoValorHtml(d.desmontagem),
    descricao_servico: rtDocEventoValorHtml(d.descricaoServico, true),
    observacao_cliente: rtDocEventoValorHtml(d.observacaoCliente, true),
    referencia_local: rtDocEventoValorHtml(d.observacaoCliente, true),
    valor_total: rtDocEventoValorHtml(dinheiro(d.valorTotal)),
    sinal: rtDocEventoValorHtml(dinheiro(d.valorSinal)),
    restante: rtDocEventoValorHtml(dinheiro(d.valorRestante)),
    forma_pagamento: rtDocEventoValorHtml((d.formaPagamento || '') + (d.quitado ? '\nPagamento quitado' : ''), true),
    data_hoje: rtDocEventoValorHtml(rtDocEventoDataExtensoHoje()),
    numero_orcamento: rtDocEventoValorHtml(d.numeroOrcamento || d.id || 'PREVIEW'),
    data_orcamento: rtDocEventoValorHtml(rtDocEventoDataBR(new Date().toISOString().slice(0,10))),
    validade_orcamento: rtDocEventoValorHtml(rtDocEventoValidadeOrcamentoBR()),
    itens: rtDocEventoItensTabelaOrcamento(d),
    valor_materiais: rtDocEventoValorHtml(dinheiro(rtDocEventoValorMateriais(d))),
    valor_frete: rtDocEventoValorHtml(dinheiro(0)),
    desconto: '',
    assinaturas: rtDocEventoAssinaturas()
  };

  return String(template || '').replace(/{{\s*([a-zA-Z0-9_]+)\s*}}/g, (m, chave) => Object.prototype.hasOwnProperty.call(mapa, chave) ? mapa[chave] : m);
}

function rtDocEventoObterModeloConfigurado(tipo, d) {
  try {
    const config = (typeof carregarConfiguracoes === 'function') ? carregarConfiguracoes() : (window.configRioTendas || {});
    const modelos = config.modelosDocumentos || {};
    const modelo = modelos && modelos[tipo] ? String(modelos[tipo]) : '';
    if (!modelo) return null;

    // Proteção: alguns modelos antigos foram salvos já preenchidos com dados de um evento/orçamento.
    // Se não houver placeholders {{...}}, usar o modelo padrão dinâmico para não repetir orçamento antigo.
    if (!/{{\s*[a-zA-Z0-9_]+\s*}}/.test(modelo)) {
      console.warn('Modelo configurado sem placeholders ignorado para evitar dados antigos no PDF:', tipo);
      return null;
    }

    return rtDocEventoAplicarModelo(modelo, d);
  } catch (erro) {
    console.warn('Não foi possível carregar modelo configurado do documento.', erro);
  }
  return null;
}


function rtDocEventoValidadeOrcamentoBR() {
  const validade = new Date();
  validade.setDate(validade.getDate() + 30);
  return rtDocEventoDataBR(validade.toISOString().slice(0,10));
}

function rtDocEventoValorMateriais(d) {
  const total = Number(d.valorTotal || 0) || 0;
  return total;
}

function rtDocEventoItensTabelaOrcamento(d) {
  const linhas = [];
  (d.produtos || []).forEach(item => {
    const desc = [item.codigo ? `Cód. ${item.codigo}` : '', item.categoria || '', item.tamanho || '', item.cor || ''].filter(Boolean).join(' — ') || 'Produto';
    linhas.push({ qtd: 1, desc, valor: '' });
  });
  (d.apoio || []).forEach(item => {
    linhas.push({ qtd: item.quantidade || 1, desc: item.nome || 'Material de apoio', valor: '' });
  });
  (d.extras || []).forEach(item => {
    linhas.push({ qtd: item.quantidade || 1, desc: item.descricao || 'Extra', valor: '' });
  });
  const corpo = linhas.length ? linhas.map(i => `<tr><td>${rtDocEventoEscape(i.qtd)}</td><td>${rtDocEventoEscape(i.desc)}</td><td>${i.valor ? dinheiro(i.valor) : '-'}</td><td>${i.valor ? dinheiro(Number(i.qtd||0)*Number(i.valor||0)) : '-'}</td></tr>`).join('') : '<tr><td colspan="4">Materiais a combinar.</td></tr>';
  return `<table class="doc-table"><thead><tr><th>Qtd</th><th>Descrição</th><th>Valor Unit.</th><th>Total</th></tr></thead><tbody>${corpo}</tbody></table>`;
}

